#if UNITY_STANDALONE_WIN && !UNITY_EDITOR
using System.Collections;
using System.IO;
using UnityEngine;
public class ReferenceCapture:MonoBehaviour {
    string folder;
    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Init(){var a=System.Environment.GetCommandLineArgs();for(int i=0;i<a.Length-1;i++)if(a[i]=="--reference-capture"){if(Application.companyName=="Pocket Playground QA"){PlayerPrefs.DeleteKey("Gaeun.Ref.Profile5");PlayerPrefs.DeleteKey("Gaeun.Ref.Unlocked");PlayerPrefs.DeleteKey("Gaeun.Ref.Selected");}var go=new GameObject("ReferenceCapture");go.AddComponent<ReferenceCapture>().folder=a[i+1];}}
    IEnumerator Start(){Directory.CreateDirectory(folder);yield return null;yield return new WaitForEndOfFrame();yield return ShotLoading();yield return new WaitForSecondsRealtime(2);yield return new WaitUntil(()=>ReferenceGame.Instance!=null&&ReferenceGame.Instance.Ready);yield return new WaitForSecondsRealtime(.7f);var g=ReferenceGame.Instance;g.LoadLevel(0);g.ShowHome();yield return Shot("01-home");Click("Daily Rewards");yield return Shot("09-attendance-ready");Click("Claim Attendance");yield return Shot("10-attendance-claimed");Click("Close Attendance");Click("Challenges");yield return Shot("11-challenges");Click("Done");Click("Collection");yield return Shot("12-collection");Click("Next","3D Collection");yield return Shot("13-collection-next");Click("Done");Click("Settings");yield return Shot("06-settings");Click("Mode");Click("Done");Click("Levels");yield return Shot("07-levels");Click("Done");Click("Shop");yield return Shot("08-boosters");Click("Done");Click("Settings");Click("Mode");Click("Done");g.StartPlay();yield return Shot("02-first-level");if(System.Array.IndexOf(System.Environment.GetCommandLineArgs(),"--ui-only")>=0){Application.Quit();yield break;}
        foreach(int index in new[]{2,3,7,11,15,22,27,28,38,90,150,300,411,461,464}){g.LoadLevel(index);g.StartPlay();yield return new WaitForSecondsRealtime(.1f);yield return Shot("level-"+(index+1));}
        g.LoadLevel(20);g.StartPlay();g.TriggerBombForTest();yield return new WaitForSecondsRealtime(1.5f);yield return Shot("03-bomb-failure");
        g.LoadLevel(0);g.StartPlay();g.TestInput=true;g.BeginStick(new Vector2(270,200));g.MoveStick(new Vector2(310,245));g.TestDirection=g.Stick.Value;yield return new WaitForSecondsRealtime(.3f);yield return Shot("04-joystick");g.TestDirection=Vector2.zero;g.LoadLevel(0);g.StartPlay();for(int frame=0;frame<1000&&g.GrowthPoints<10;frame++){g.MoveHoleForTest(g.NearestCollectible());yield return null;}yield return Shot("05-growth");g.LoadLevel(15);g.StartPlay();Click("Booster2");yield return Shot("14-finder");g.Pause();yield return Shot("15-pause");g.Resume();g.SetCountdownForTest(.01f);yield return new WaitForSecondsRealtime(.1f);yield return Shot("16-time-failure");g.LoadLevel(15);g.StartPlay();yield return new WaitForSecondsRealtime(1);var times=new System.Collections.Generic.List<float>();for(int i=0;i<180;i++){yield return null;times.Add(Time.unscaledDeltaTime*1000);}times.Sort();File.WriteAllText(Path.Combine(folder,"DesktopFrameTimes.txt"),"Windows standalone, D3D11, "+Screen.width+"x"+Screen.height+", stage 16, stationary, 180 frame samples. Not an Android performance test.\nActors: "+g.ActorCount+"; visible at end: "+g.RenderedActors+"\nMedian ms: "+times[90]+"\np95 ms: "+times[171]+"\n");Application.Quit();}
    IEnumerator ShotLoading(){
        var overlay=GameObject.Find("Coton Loading").GetComponent<Canvas>();var camera=GameObject.Find("Loading Camera").GetComponent<Camera>();
        var rt=new RenderTexture(Screen.width,Screen.height,24){antiAliasing=2};camera.targetTexture=rt;camera.aspect=(float)Screen.width/Screen.height;camera.cullingMask=~0;overlay.renderMode=RenderMode.ScreenSpaceCamera;overlay.worldCamera=camera;overlay.planeDistance=1;
        Canvas.ForceUpdateCanvases();yield return null;Canvas.ForceUpdateCanvases();camera.Render();var previous=RenderTexture.active;RenderTexture.active=rt;var img=new Texture2D(Screen.width,Screen.height,TextureFormat.RGB24,false);img.ReadPixels(new Rect(0,0,Screen.width,Screen.height),0,0);img.Apply();File.WriteAllBytes(Path.Combine(folder,"00-loading.png"),img.EncodeToPNG());RenderTexture.active=previous;camera.targetTexture=null;camera.cullingMask=0;overlay.renderMode=RenderMode.ScreenSpaceOverlay;Destroy(img);rt.Release();Destroy(rt);
    }
    void Click(string name,string parent=null){foreach(var b in Object.FindObjectsByType<UnityEngine.UI.Button>(FindObjectsSortMode.None))if(b.name==name&&(parent==null||b.transform.parent.name==parent)){b.onClick.Invoke();return;}throw new System.Exception("Capture button missing "+name);}
    IEnumerator Shot(string name){yield return new WaitForSecondsRealtime(.2f);var cam=Camera.main;var canvas=Object.FindFirstObjectByType<Canvas>();var rt=new RenderTexture(Screen.width,Screen.height,24){antiAliasing=2};cam.targetTexture=rt;cam.aspect=(float)Screen.width/Screen.height;canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=cam;canvas.planeDistance=1;Canvas.ForceUpdateCanvases();yield return null;yield return null;ReferenceGame.Instance.RenderForCapture();cam.Render();var previous=RenderTexture.active;RenderTexture.active=rt;var img=new Texture2D(Screen.width,Screen.height,TextureFormat.RGB24,false);img.ReadPixels(new Rect(0,0,Screen.width,Screen.height),0,0);img.Apply();File.WriteAllBytes(Path.Combine(folder,name+".png"),img.EncodeToPNG());RenderTexture.active=previous;cam.targetTexture=null;canvas.renderMode=RenderMode.ScreenSpaceOverlay;Destroy(img);rt.Release();Destroy(rt);}
}
#endif

